subset-construction.pseudocode:
def eps_closure(nfa, states):
    stack, closure = list(states), set(states)
    while stack:
        for r in nfa.eps.get(stack.pop(), []):  # ε 전이
            if r not in closure:
                closure.add(r)
                stack.append(r)
    return frozenset(closure)

def move(nfa, T, a):
    return {r for q in T for r in nfa.delta.get((q, a), ())}

def subset_construction(nfa):
    start = eps_closure(nfa, {nfa.start})
    dstates, work, trans = {start}, [start], {}
    while work:  # 미표시 DFA 상태 처리
        T = work.pop()
        for a in nfa.alphabet:
            U = eps_closure(nfa, move(nfa, T, a))
            trans[(T, a)] = U  # 빈 집합 = 죽은 상태
            if U not in dstates:
                dstates.add(U)
                work.append(U)
    accept = {S for S in dstates if S & nfa.accepts}
    return dstates, start, trans, accept

substitution-cipher.pseudocode:
def caesar(text, k):  # 단일 치환: 고정 이동
    out = []
    for ch in text:
        if ch.isupper():
            out.append(chr((ord(ch) - 65 + k) % 26 + 65))
        else:
            out.append(ch)  # 대문자 외는 그대로
    return ''.join(out)

def vigenere(text, key):  # 다중 치환: 위치별 이동량
    out = []
    for i, ch in enumerate(text):
        k = ord(key[i % len(key)]) - 65
        out.append(chr((ord(ch) - 65 + k) % 26 + 65))
    return ''.join(out)

